WITH latest AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY product_id ORDER BY last_restock DESC, id) AS row_num FROM inventory QUALIFY row_num = 1), deduped AS (SELECT * FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY store_id, product_id ORDER BY row_num, id) AS dedup_rank FROM latest) ranked WHERE dedup_rank = 1), enriched AS (SELECT id, store_id, product_id, quantity, last_restock, row_num, dedup_rank, AVG(quantity) OVER (PARTITION BY store_id ORDER BY dedup_rank, id ROWS BETWEEN 5 PRECEDING AND CURRENT ROW) AS quantity_avg_5, CUME_DIST() OVER (PARTITION BY store_id ORDER BY quantity NULLS LAST) AS quantity_cume_dist, AVG(quantity) OVER w_part AS product_id_avg_quantity FROM deduped WINDOW w_part AS (PARTITION BY product_id)), metrics AS (SELECT *, NTILE(5) OVER w_grp AS quantity_cume_dist_bucket, SUM(quantity_avg_5) OVER (ORDER BY quantity_avg_5, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_quantity_avg_5, NTILE(10) OVER w_hist AS product_id_avg_quantity_bucket, LEAD(quantity_avg_5, 2, 0) OVER (PARTITION BY store_id, product_id ORDER BY dedup_rank, id) AS next_quantity_avg_5 FROM enriched WINDOW w_grp AS (PARTITION BY product_id, store_id ORDER BY quantity_cume_dist, id), w_hist AS (PARTITION BY store_id ORDER BY product_id_avg_quantity DESC, id)), cleaned AS (SELECT *, LEAST(dedup_rank, running_quantity_avg_5) AS least_dedup_rank_running_quantity_avg_5 FROM metrics WHERE last_restock >= DATE '2024-02-17'), with_dims AS (SELECT e.*, d.brand, d.price, d.category FROM cleaned e INNER JOIN products d ON e.product_id = d.id), base AS (SELECT *, ROUND(quantity, 2) AS quantity_rounded FROM with_dims WHERE last_restock >= DATE '2023-06-29') SELECT DATE_TRUNC('QUARTER', last_restock) AS quarter_start, DATE_TRUNC('YEAR', last_restock) AS year_start, SORT_ARRAY(COLLECT_SET(category)) AS category_list, SUM(CASE WHEN brand = 'Acme' THEN product_id_avg_quantity ELSE 0 END) AS acme_product_id_avg_quantity, SUM(CASE WHEN category = 'Home' THEN price ELSE 0 END) AS home_price FROM base GROUP BY DATE_TRUNC('QUARTER', last_restock), DATE_TRUNC('YEAR', last_restock) HAVING acme_product_id_avg_quantity >= 0 ORDER BY quarter_start;
